import * as T from 'three';
import {OrbitControls} from 'three/examples/jsm/controls/OrbitControls.js';
const $=id=>document.getElementById(id),base='/output/photo-cc0-review',key='sully.photo.cc0-review.20261004';
const [{entries},pairs]=await Promise.all([fetch(base+'/catalog.json').then(r=>r.json()),fetch(base+'/pairs.json').then(r=>r.json())]);
const all=[...entries,...pairs],byId=new Map(all.map(e=>[e.id,e]));let filter='new',current=null,generation=0,saved=new Set();try{saved=new Set(JSON.parse(localStorage.getItem(key)||'[]'));}catch{}
const scene=new T.Scene();scene.background=new T.Color('#e8eee4');scene.add(new T.HemisphereLight('#ffffff','#829080',2.4));const light=new T.DirectionalLight('#fff3df',2);light.position.set(3,5,4);scene.add(light);
const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));$('stage').append(renderer.domElement);
const camera=new T.PerspectiveCamera(35,1,.01,100),controls=new OrbitControls(camera,renderer.domElement),group=new T.Group();scene.add(group);controls.minDistance=.5;controls.maxDistance=15;
scene.add(new T.GridHelper(8,32,'#aec0ae','#d1dacf'));
const sphere=new T.SphereGeometry(1,12,8),cylinder=new T.CylinderGeometry(1,1,1,10),materials=['#548573','#b88667'].map(color=>new T.MeshStandardMaterial({color,roughness:1}));
let bounds=new T.Box3(),center=new T.Vector3(),extent=new T.Vector3();
function render(){renderer.render(scene,camera);}controls.addEventListener('change',render);
new ResizeObserver(()=>{const r=$('stage').getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();render();}).observe($('stage'));
function view(direction='front'){const d=Math.max(extent.x,extent.y,extent.z,1.8)*1.8*Math.max(1,1/camera.aspect);controls.target.copy(center);camera.position.copy(center).add(new T.Vector3(direction==='side'?d:0,d*.06,direction==='side'?0:direction==='back'?-d:d));controls.update();render();}
function actor(data,index,offset=0,rotation=0){const root=new T.Group(),points=data.frames[0];const nodes=data.names.map((name,i)=>new T.Vector3().fromArray(points,i*3));
 nodes.forEach((p,i)=>{const name=data.names[i],finger=/finger|toe/.test(name),radius=finger?.008:.025;const joint=new T.Mesh(sphere,materials[index]);joint.position.copy(p);joint.scale.setScalar(/head/i.test(name)?.095:radius*1.2);root.add(joint);const parent=data.parents[i];if(parent>=0){const q=nodes[parent],delta=p.clone().sub(q);if(delta.length()>1e-6){const limb=new T.Mesh(cylinder,materials[index]);limb.position.copy(p).lerp(q,.5);limb.scale.set(radius,delta.length(),radius);limb.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),delta.normalize());root.add(limb);}}});root.position.x=offset;root.rotation.y=rotation;group.add(root);}
function visible(){const q=$('search').value.toLowerCase();return all.filter(e=>(filter==='new'?e.newBatch:filter==='single'?!e.derived:filter==='pair'?e.derived:saved.has(e.id))&&`${e.name} ${e.original||''} ${e.source||''}`.toLowerCase().includes(q));}
function list(){document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.filter===filter));const frag=document.createDocumentFragment();for(const e of visible()){const b=document.createElement('button');b.dataset.id=e.id;b.setAttribute('aria-pressed',e.id===current?.id);const src=e.thumbnail||(e.derived?byId.get(e.actors[0].id).thumbnail:null);if(src){const img=new Image();img.src=src;img.loading='lazy';img.alt=e.name;b.append(img);}const title=document.createElement('strong');title.textContent=(saved.has(e.id)?'★ ':'')+e.name;const note=document.createElement('small');note.textContent=e.derived?'双人组合示意 · 非原生双人':e.category+' · CC0';b.append(title,note);b.onclick=()=>load(e.id);frag.append(b);}$('cards').replaceChildren(frag);$('mark').textContent=saved.has(current?.id)?'★ 已勾选':'☆ 加入待确认';}
async function load(id){const token=++generation,e=byId.get(id);current=e;list();$('title').textContent=e.name;$('status').textContent='读取本地姿势…';try{const roles=e.derived?e.actors:[{id}];const data=await Promise.all(roles.map(a=>fetch(byId.get(a.id).preview).then(r=>{if(!r.ok)throw Error('文件缺失');return r.json();})));if(token!==generation)return;group.clear();data.forEach((d,i)=>actor(d,i,roles[i].x,roles[i].rotation));bounds.setFromObject(group);bounds.getCenter(center);bounds.getSize(extent);view();$('detail').textContent=e.derived?'由两份 CC0 单人姿势并置，未做接触修正或身高适配。仅确认构图意向。':e.original+' · '+e.source+' · 源第 0 帧；骨架用于查看关节，原缩略图仅供对照。';$('source').replaceChildren();for(const r of roles){const src=byId.get(r.id);for(const [label,url]of [['来源 / CC0',src.sourceUrl],['下载 BVH',src.files[0]]]){const a=document.createElement('a');a.textContent=label;a.href=url;a.target='_blank';a.rel='noopener';$('source').append(a);}}$('status').textContent='已载入 · '+(all.indexOf(e)+1)+' / '+all.length;window.__photoReview={current:e.id,count:all.length,actors:roles.length,ready:true};}catch(error){$('status').textContent=String(error);}}
for(const d of ['front','side','back'])$(d).onclick=()=>view(d);
for(const [id,delta]of [['prev',-1],['next',1]])$(id).onclick=()=>{const v=visible();if(v.length)load(v[(v.findIndex(e=>e.id===current?.id)+delta+v.length)%v.length].id);};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;list();const first=visible()[0];if(first)load(first.id);});$('search').oninput=list;
$('mark').onclick=()=>{if(!current)return;saved.has(current.id)?saved.delete(current.id):saved.add(current.id);localStorage.setItem(key,JSON.stringify([...saved]));list();};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify({kind:'photo-cc0-review',status:'user-shortlist-not-integrated',entries:[...saved].map(id=>byId.get(id)).filter(Boolean)},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='拍照姿势待确认.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
window.__loadPhotoCandidate=load;window.render_game_to_text=()=>JSON.stringify(window.__photoReview);window.advanceTime=()=>render();list();await load(visible()[0].id);
